Subroutine DiasDelMes(mes As Integer) As Integer
  Switch mes Do
    2:
      Return 28;
    4, 6, 9, 11:
      Return 30;
    Otherwise:
      Return 31;
  EndSwitch
EndSubroutine

Subroutine ValidarFecha(dia As Integer, mes As Integer) As Result<Integer, String>
  If mes < 1 Or mes > 12 Then
    Return Failure("mes fuera de rango");
  EndIf
  If dia < 1 Or dia > DiasDelMes(mes) Then
    Return Failure("día fuera de rango");
  EndIf
  Return Success(dia);
EndSubroutine

Algorithm Fecha
  Define dia, mes As Integer;
  Read dia;
  Read mes;
  Switch ValidarFecha(dia, mes) Do
    Success(valor): Write "válida";
    Failure(motivo): Write motivo;
  EndSwitch
EndAlgorithm
